def flood_fill(image, sr, sc, color):
    n, m = len(image), len(image[0])
    src = image[sr][sc]
    if src == color:
        return image
    def dfs(i, j):
        if not (0 <= i < n and 0 <= j < m) or image[i][j] != src:
            return
        image[i][j] = color
        for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
            dfs(i + di, j + dj)
    dfs(sr, sc)
    return image

from collections import deque

def flood_fill_bfs(image, sr, sc, color):
    n, m = len(image), len(image[0])
    src = image[sr][sc]
    if src == color:
        return image
    q = deque([(sr, sc)])
    image[sr][sc] = color
    while q:
        i, j = q.popleft()
        for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < m and image[ni][nj] == src:
                image[ni][nj] = color
                q.append((ni, nj))
    return image
